import socket
import sys
import time
import random
import errno

_original_socket = socket.socket

CORRUPTED_RCVBUF = 128
CORRUPTED_SNDBUF = 128
MAX_RECV_CHUNK = 16
MAX_SEND_CHUNK = 16
CORRUPTION_ACTIVE = True
FAILURE_RATE = 0.25

class CorruptedTCPSocket(_original_socket):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._initialized = False

    def connect(self, address):
        result = super().connect(address)
        if not self._initialized:
            self._apply_corrupted_params()
        return result

    def connect_ex(self, address):
        result = super().connect_ex(address)
        if result == 0 and not self._initialized:
            self._apply_corrupted_params()
        return result

    def bind(self, address):
        result = super().bind(address)
        if not self._initialized:
            self._apply_corrupted_params()
        return result

    def _apply_corrupted_params(self):
        try:
            super().setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF, CORRUPTED_RCVBUF)
            super().setsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF, CORRUPTED_SNDBUF)
            self._initialized = True
        except (OSError, AttributeError):
            pass

    def recv(self, bufsize, flags=0):
        if not CORRUPTION_ACTIVE:
            return super().recv(bufsize, flags)

        if random.random() < FAILURE_RATE:
            time.sleep(0.05)
            if random.random() < 0.3:
                raise socket.timeout("recv timed out due to window starvation")

        limited_size = min(bufsize, MAX_RECV_CHUNK)
        if random.random() < 0.4:
            time.sleep(0.005)
        return super().recv(limited_size, flags)

    def recv_into(self, buffer, nbytes=0, flags=0):
        if not CORRUPTION_ACTIVE:
            return super().recv_into(buffer, nbytes, flags)
        if nbytes == 0:
            nbytes = len(buffer)
        limited_size = min(nbytes, MAX_RECV_CHUNK)
        return super().recv_into(buffer, limited_size, flags)

    def send(self, data, flags=0):
        if not CORRUPTION_ACTIVE:
            return super().send(data, flags)

        if random.random() < FAILURE_RATE:
            time.sleep(0.05)
            if random.random() < 0.3:
                raise OSError(errno.ENOBUFS, "No buffer space available - window exhausted")

        limited_data = data[:MAX_SEND_CHUNK]
        if random.random() < 0.4:
            time.sleep(0.005)
        return super().send(limited_data, flags)

    def sendall(self, data, flags=0):
        if not CORRUPTION_ACTIVE:
            return super().sendall(data, flags)
        total_sent = 0
        while total_sent < len(data):
            if random.random() < FAILURE_RATE * 0.5:
                time.sleep(0.05)
                if random.random() < 0.2:
                    raise OSError(errno.ENOBUFS, "No buffer space available during sendall")

            chunk = data[total_sent:total_sent + MAX_SEND_CHUNK]
            if random.random() < 0.3:
                time.sleep(0.008)
            sent = super().send(chunk, flags)
            if sent == 0:
                raise OSError("socket connection broken")
            total_sent += sent

    def setsockopt(self, level, optname, value, optlen=None):
        if level == socket.SOL_SOCKET:
            if optname == socket.SO_RCVBUF:
                value = min(value, CORRUPTED_RCVBUF) if isinstance(value, int) else value
            elif optname == socket.SO_SNDBUF:
                value = min(value, CORRUPTED_SNDBUF) if isinstance(value, int) else value

        if optlen is not None:
            return super().setsockopt(level, optname, value, optlen)
        else:
            return super().setsockopt(level, optname, value)

socket.socket = CorruptedTCPSocket
